        // 新的大幅修订 6100 → 6800 以版本 2 为基准重新待确认，见证后生效为修订号 3
        postJson("/api/equipment/eq-d/readings/r1/revisions", """
                {"requestId":"rev-a2","expectedVersion":4,"cumulativeMinutes":6800,
