                .andExpect(jsonPath("$[1].cumulativeMinutes").value(6100))
                .andExpect(jsonPath("$[2].cumulativeMinutes").value(6800));
        mockMvc.perform(get("/api/equipment/eq-d/readings/r1/revision-requests"))
                .andExpect(jsonPath("$", hasSize(2)))
